{
  "id": "ch3-algorithm-modeling-recursion-traversal",
  "title": "第三章 算法建模、递归与遍历：用结构解决实际问题",
  "subtitle": "依据访问模式选择线性或半线性结构，并以递归/遍历框架实现算法",
  "language": "zh-CN",
  "audience": "计算机科学本科低年级学生",
  "theme": "slate",
  "tutor": {
    "suggestions": [
      "栈和队列的核心区别是什么？",
      "KMP 的 next 数组为什么能避免主串指针回退？",
      "为什么还原二叉树通常需要中序序列？",
      "递归遍历树的空间复杂度由什么决定？"
    ],
    "kb": [
      {
        "pattern": "栈|stack|LIFO",
        "answer": "栈是只允许在一端进行插入和删除的线性表，后进先出（LIFO）。典型应用包括表达式求值、括号匹配、函数调用栈、回溯、撤销操作。"
      },
      {
        "pattern": "队列|queue|FIFO",
        "answer": "队列是只允许在一端插入、另一端删除的线性表，先进先出（FIFO）。典型应用包括 BFS、缓冲区、任务调度、层次遍历、打印队列。"
      },
      {
        "pattern": "KMP|模式匹配|next 数组",
        "answer": "KMP 是一种线性时间字符串匹配算法。它利用模式串自身的最长相等前后缀信息构造 next 数组，失配时让模式串回退到合适位置，而主串指针不回退。"
      },
      {
        "pattern": "孩子兄弟表示法|树转二叉树|森林转二叉树",
        "answer": "孩子兄弟表示法把节点的第一个孩子作为二叉树的左孩子，右兄弟作为右孩子，从而把树或森林唯一地转换成一棵二叉树。"
      },
      {
        "pattern": "遍历序列还原|中序|先序|后序",
        "answer": "先序或后序提供根的位置，中序提供左右子树的划分边界；因此通常需要中序配合先序/后序才能唯一确定一棵二叉树。"
      },
      {
        "pattern": "递归工作栈|递归深度|空间复杂度",
        "answer": "递归调用时系统用隐式工作栈保存返回地址和局部变量，其深度等于树高 h；斜树时 h=n，空间复杂度为 O(n)，可能引发栈溢出。"
      }
    ]
  },
  "scenes": [
    {
      "id": "s3-1-access-mode",
      "kind": "content",
      "eyebrow": "3.1 结构即访问模式",
      "headline": "先问怎么访问，再问用什么结构",
      "lead": "线性表与树的分野，本质上是数据被访问的顺序：后进先出、先进先出、按层展开，还是随机定位。",
      "notes": "讲者备注：先让学生回忆生活中的顺序场景——食堂排队、电梯、浏览器回退。强调“访问模式”是结构选择的第一性原理：同样的数据，访问顺序不同，结构就不同。提醒学生不要先背“树用来存层次数据”，而要先问“操作是压入弹出、入队出队，还是按层遍历”。",
      "blocks": [
        {
          "id": "b1_stmt",
          "type": "statement",
          "intent": "点明结构选择的核心依据是访问模式",
          "size": "m",
          "content": "数据结构不是先验标签，而是问题访问模式的投影：**LIFO** 选栈，**FIFO** 选队列，**层次关系**选树，**随机访问**选顺序表或哈希表。"
        },
        {
          "id": "b1_flow",
          "type": "flow",
          "intent": "展示从问题描述到结构选择的抽象过程",
          "size": "l",
          "content": "1. 读题，提取操作序列；2. 判断访问顺序（LIFO / FIFO / 层次 / 随机）；3. 抽象出“节点”与“关系”；4. 选择线性或半线性结构；5. 用递归或遍历实现算法。"
        },
        {
          "id": "b1_list",
          "type": "list",
          "intent": "给出从问题到抽象的三问",
          "size": "m",
          "content": "- 哪些实体是**节点**？\n- 节点之间是**前后**、**父子**还是**邻接**关系？\n- 操作是**压入/弹出**、**入队/出队**，还是**遍历子树**？"
        },
        {
          "id": "b1_callout",
          "type": "callout",
          "intent": "提示字符串作为特殊线性表及其模式匹配思想",
          "size": "s",
          "content": "字符串可视为元素为字符的线性表，但模式匹配要求利用前缀后缀重叠信息；KMP 在顺序扫描中隐藏了“回退”的栈式直觉。"
        }
      ]
    },
    {
      "id": "s3-2-linear-apps",
      "kind": "content",
      "eyebrow": "3.2 线性结构的典型战场",
      "headline": "栈、队列与字符串：三种顺序，三类问题",
      "lead": "括号匹配、任务调度、文本搜索，本质都是把现实世界中的“顺序约束”翻译成线性操作。",
      "notes": "讲者备注：每个应用都要落到具体动作：括号匹配中，左括号是“期待”，右括号是“兑现”；任务调度中，队列保证公平性；KMP 的 next 数组是“利用已知信息避免重复比较”的典型。runnable 让学生修改测试串，观察栈空或不匹配时的返回。",
      "blocks": [
        {
          "id": "b2_stack",
          "type": "list",
          "intent": "枚举栈的五种典型应用",
          "size": "m",
          "content": "**栈的五种典型场景**\n- 表达式求值：操作数栈 + 运算符栈\n- 括号匹配：遇左括号压栈，遇右括号弹栈核对\n- 函数调用栈：保存返回地址与局部变量\n- 回溯：显式栈保存已走路径\n- 撤销操作：Undo 栈记录逆操作"
        },
        {
          "id": "b2_queue",
          "type": "list",
          "intent": "枚举队列的五种典型应用",
          "size": "m",
          "content": "**队列的五种典型场景**\n- BFS：逐层扩展 frontier\n- 缓冲区：数据流削峰填谷\n- 任务调度：CPU / 线程就绪队列\n- 层次遍历：树按层访问\n- 打印队列：先到先服务"
        },
        {
          "id": "b2_kmp",
          "type": "callout",
          "intent": "概括 KMP 的核心思想",
          "size": "s",
          "content": "KMP 的核心：当模式串在位置 $j$ 失配时，利用已匹配部分的**最长相等前后缀**，将 $j$ 跳转到 $next[j]$，避免主串指针回退。"
        },
        {
          "id": "b2_runnable",
          "type": "runnable",
          "intent": "动手验证括号匹配算法",
          "size": "l",
          "language": "python",
          "content": "def is_valid(s):\n    stack = []\n    pairs = {')': '(', ']': '[', '}': '{'}\n    for ch in s:\n        if ch in pairs.values():\n            stack.append(ch)\n        elif ch in pairs:\n            if not stack or stack.pop() != pairs[ch]:\n                return False\n    return not stack\n\ntests = ['()', '([)]', '{[]}', '(((', '()[]{}']\nfor t in tests:\n    print(t, '->', is_valid(t))"
        }
      ]
    },
    {
      "id": "s3-3-tree-model",
      "kind": "content",
      "eyebrow": "3.3 半线性结构：树",
      "headline": "树是递归定义的层次结构",
      "lead": "文件系统、组织架构、XML/JSON 解析，都是“一个根节点挂若干子树”的半线性模型。",
      "transition": "zoom",
      "notes": "讲者备注：用文件系统做锚点：/home/user/docs 中 home 是根，user 是子树，docs 是孙树。二叉树的五种形态是递归定义的基例。孩子兄弟表示法是树与二叉树互换的桥梁，也是许多实际库（如 Linux 进程树）的实现方式。",
      "blocks": [
        {
          "id": "b3_def",
          "type": "statement",
          "intent": "给出树的递归定义",
          "size": "m",
          "content": "一棵树要么为空，要么由一个**根节点**和若干棵互不相交的**子树**（即森林）组成。"
        },
        {
          "id": "b3_apps",
          "type": "list",
          "intent": "列举树的五种典型应用",
          "size": "m",
          "content": "**树的典型应用**\n- 文件系统：目录为根，文件/子目录为子树\n- 组织结构：部门—团队—成员\n- XML/JSON 解析：DOM / AST\n- 决策树：节点为判断，叶子为结论\n- 索引：B/B+ 树、Trie"
        },
        {
          "id": "b3_forms",
          "type": "diagram",
          "shape": "connected-circles",
          "intent": "展示二叉树的五种基本形态",
          "size": "l",
          "content": "二叉树的五种基本形态：1) 空树；2) 仅含根节点；3) 根 + 左子树；4) 根 + 右子树；5) 根 + 左右子树。每种形态本身又是一棵二叉树，体现递归性质。"
        },
        {
          "id": "b3_convert",
          "type": "flow",
          "intent": "说明树、森林与二叉树的相互转换",
          "size": "m",
          "content": "**孩子兄弟表示法**\n1. 节点的第一个孩子 → 二叉树的左孩子\n2. 节点的右兄弟 → 二叉树的右孩子\n3. 森林中下一棵树的根视为上一棵根的右兄弟"
        }
      ]
    },
    {
      "id": "s3-4-traversal",
      "kind": "content",
      "eyebrow": "3.4 遍历与递归",
      "headline": "遍历序列是树在纸上的投影",
      "lead": "先序、中序、后序、层次遍历，既是递归定义的延伸，也是显式栈/队列的迭代实现。",
      "notes": "讲者备注：递归与迭代的对应是本章难点。递归中序的函数调用栈，和迭代中序的显式栈，保存的是同一类信息：当前节点及其右子树待访问。强调斜树导致 O(n) 递归深度，可能栈溢出。数学归纳法证明 n0=n2+1 时，先验证基例，再假设子树成立推导整棵树。",
      "blocks": [
        {
          "id": "b4_orders",
          "type": "agenda",
          "intent": "列出四种遍历的访问顺序",
          "size": "m",
          "content": "- 先序：根 → 左 → 右（DLR）\n- 中序：左 → 根 → 右（LDR）\n- 后序：左 → 右 → 根（LRD）\n- 层次：按层从左到右"
        },
        {
          "id": "b4_recur",
          "type": "code",
          "intent": "给出递归中序遍历实现",
          "size": "m",
          "content": "def inorder(r):\n    if r:\n        inorder(r.left)\n        print(r.val)\n        inorder(r.right)"
        },
        {
          "id": "b4_iter",
          "type": "code",
          "intent": "给出迭代中序遍历实现，对应显式栈",
          "size": "m",
          "content": "def inorder_iter(r):\n    s = []\n    while r or s:\n        while r:\n            s.append(r)\n            r = r.left\n        r = s.pop()\n        print(r.val)\n        r = r.right"
        },
        {
          "id": "b4_recon",
          "type": "callout",
          "intent": "解释遍历序列还原二叉树的关键",
          "size": "s",
          "content": "为何还原二叉树通常需要**中序**配合先序/后序？中序能区分左、右子树的边界，而先序/后序只告诉根的位置。"
        },
        {
          "id": "b4_depth",
          "type": "callout",
          "intent": "联系递归工作栈、显式栈与数学归纳法",
          "size": "s",
          "content": "递归深度等于隐式工作栈高度，空间代价为 $O(h)$；斜树时 $h=n$，可能栈溢出。用数学归纳法可证：二叉树叶子数 $n_0$ 与度为 2 的节点数 $n_2$ 满足 $n_0 = n_2 + 1$。"
        }
      ]
    },
    {
      "id": "s3-5-quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "lead": "五道小题检验你是否能把问题描述映射到结构，并预判遍历行为。",
      "notes": "讲者备注：quiz 后快速点评：第 1 题点出“双栈”可模拟浏览器前进后退；第 4 题强调中序的“分界”作用；第 5 题联系实际工程中递归深度限制（如 Python 默认 1000）。",
      "blocks": [
        {
          "id": "b5_quiz",
          "type": "quiz",
          "intent": "考察结构选择、栈队列应用、KMP、遍历还原与递归深度",
          "size": "l",
          "questions": [
            {
              "q": "浏览器“前进/后退”按钮最适合用哪种结构实现？",
              "options": ["栈", "队列", "树", "图"],
              "answer": "栈"
            },
            {
              "q": "操作系统进程调度中的就绪队列主要体现什么访问模式？",
              "options": ["LIFO", "FIFO", "随机访问", "层次访问"],
              "answer": "FIFO"
            },
            {
              "q": "KMP 算法中的 next 数组利用的是模式串的什么信息？",
              "options": ["最长相等前后缀", "中序遍历序列", "哈希值", "随机种子"],
              "answer": "最长相等前后缀"
            },
            {
              "q": "已知先序和中序可唯一确定二叉树，主要因为中序提供了什么？",
              "options": ["根的位置", "左右子树的边界", "树的高度", "叶子数量"],
              "answer": "左右子树的边界"
            },
            {
              "q": "递归遍历一棵深度为 n 的斜树，空间复杂度是？",
              "options": ["O(1)", "O(log n)", "O(n)", "O(n²)"],
              "answer": "O(n)"
            }
          ]
        }
      ]
    }
  ]
}
